'use strict';

async function runStages(initialValue, stages) {
  if (!Array.isArray(stages)) {
    throw new TypeError('stages must be an array');
  }
  for (let index = 0; index < stages.length; index += 1) {
    if (typeof stages[index] !== 'function') {
      throw new TypeError('every stage must be a function');
    }
  }

  let value = initialValue;
  for (let index = 0; index < stages.length; index += 1) {
    value = await Reflect.apply(stages[index], undefined, [value]);
  }
  return value;
}

module.exports = { runStages };
